intfalsefileperms stringfilename
Restituisce i permessi del file indicato.

  &reftitle.examples;



    Mostra i permessi come valore ottale


<?php
echo substr(sprintf('%o', fileperms('/tmp')), -4);
echo substr(sprintf('%o', fileperms('/etc/passwd')), -4);
?>


    &example.outputs;


1777
0644




    Mostra i permessi completi


<?php
$perms = fileperms('/etc/passwd');

switch ($perms & 0xF000) {
    case 0x1000: $info = 'p'; break; // pipe FIFO
    case 0x2000: $info = 'c'; break; // file speciale a caratteri
    case 0x4000: $info = 'd'; break; // directory
    case 0x6000: $info = 'b'; break; // file speciale a blocchi
    case 0x8000: $info = '-'; break; // file regolare
    case 0xA000: $info = 'l'; break; // collegamento simbolico (ottenibile usando la funzione lstat)
    case 0xC000: $info = 's'; break; // socket

    // sconosciuto
    default: $info = 'u';
}

// Proprietario
$setuid = $perms & 0x0800;
$info .= (($perms & 0x0100) ? 'r' : '-');
$info .= (($perms & 0x0080) ? 'w' : '-');
$info .= (($perms & 0x0040) ? ($setuid ? 's' : 'x') : ($setuid ? 'S' : '-'));

// Gruppo
$setgid = $perms & 0x0400;
$info .= (($perms & 0x0020) ? 'r' : '-');
$info .= (($perms & 0x0010) ? 'w' : '-');
$info .= (($perms & 0x0008) ? ($setgid ? 's' : 'x') : ($setgid ? 'S' : '-'));

// Altri
$sticky = $perms & 0x0200;
$info .= (($perms & 0x0004) ? 'r' : '-');
$info .= (($perms & 0x0002) ? 'w' : '-');
$info .= (($perms & 0x0001) ? ($sticky ? 't' : 'x') : ($sticky ? 'T' : '-'));

echo $info;
?>


    &example.outputs;


